import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Conclusioni","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffebe.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffebe.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffebe.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="conclusioni" tabindex="-1">Conclusioni <a class="header-anchor" href="#conclusioni" aria-label="Permalink to “Conclusioni”">​</a></h1><p>Allora siamo riusciti a costruire una geometria dove, data una retta ed un punto fuori di essa, si possono tracciare:</p><ul><li>infinite rette parallele</li><li>due rette parallele</li><li>nessuna retta parallela</li></ul><p>Ma allora i postulati sono veri di per sé, oppure possiamo prendere i postulati a piacere e poi costruire come vogliamo? Chi ti dice che non sia valida nel mondo reale la geometria di Klein oppure quella di Lobacewskij? Anche gli altri postulati possono essere sottoposti a critica: considera il postulato:</p><p><strong>La retta divide il piano in due parti tali che prendendo due punti dalla stessa parte il segmento che li unisce non taglia la retta, mentre prendendo due punti da parti opposte il segmento che li unisce taglia la retta</strong></p><blockquote><p>Immagina che il piano sia la coperta di un letto: finché la coperta è stesa bene siamo d&#39;accordo che vale il postulato, ma se fai fare le grinze alla coperta e l&#39;accartocci puoi pensare un segmento che congiunga i due punti senza tagliare la retta? Direi proprio di sì... Ma il nostro spazio è curvo (come la coperta stropicciata) con le pieghe (pozzi) dove si trovano le masse gravitazionali, quindi...</p></blockquote><p>Allora cosa c&#39;entra la geometria con il mondo reale? In effetti fu una vera rivoluzione: fu il naufragio della concezione classica del mondo con un&#39;unica realtà scientifica, che aveva dominato la scena per millenni. Cominciò così un&#39;opera di ricostruzione per definire la matematica su nuove basi più generali, senza i legami che ne avevano frenato lo sviluppo.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};